let palette = [];
let ctx;
let connectionNodes = [];

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	background('#000000');
	blendMode(ADD);
	noFill();

	stroke('#a0a0a0');
	strokeWeight(width * 0.001);
	square(width / 2, height / 2, width * 0.96);
	square(width / 2, height / 2, width * 0.95);

	divideRect(width / 2, height / 2, width * 0.95, 5);

	ctx.setLineDash([0]);
	for (let p of connectionNodes) {
		let d = width * 0.005;
		applyRandomStyle();
		circle(p.x, p.y, p.d * random(0.2));
		circle(p.x, p.y, p.d * 0.02);
	}

	let connectionAttempts = 10;
	if (connectionNodes.length > 0) {
		for (let i = 0; i < connectionAttempts; i++) {
			let p1 = random(connectionNodes);
			let p2 = random(connectionNodes);
			let d = dist(p1.x, p1.y, p2.x, p2.y);
			applyRandomStyle();
			line(p1.x, p1.y, p2.x, p2.y);
		}
	}
}

function draw() {
  // === Variant 3: Fractal Orbit Matrix ===
  gridOffset = noise(frameCount * 0.01) * 80;
  push();
  translate(gridOffset, -gridOffset);



  pop();
}

function divideRect(x, y, w, depth) {
	let cellCount = random([1, 2]);
	let cellW = w / cellCount;
	let margin = width * 0.004;

	if (depth > 0) {
		depth--;
		for (let i = 0; i < cellCount; i++) {
			for (let j = 0; j < cellCount; j++) {
				let cellX = i * cellW + x - (w / 2) + (cellW / 2);
				let cellY = j * cellW + y - (w / 2) + (cellW / 2);
				divideRect(cellX, cellY, cellW, depth);
			}
		}
	} else {
		generateElements(x, y, w - margin);
	}
}

function generateElements(x, y, w) {
	applyRandomStyle();
	square(x, y, w);

	let edgePointCount = int(random(3));
	let shapeDensity = 11;

	for (let j = 0; j < edgePointCount; j++) {
		let xx = x + random(-1, 1) * -(w / 2);
		let yy = y + random([-1, 1]) * (w / 2);
		if (random() < 0.5) {
			xx = x + random([-1, 1]) * (w / 2);
			yy = y + random(-1, 1) * -(w / 2);
		}
		connectionNodes.push({ x: xx, y: yy, d: w });
	}

	for (let i = 0; i < shapeDensity; i++) {
		let type = int(random(4));
		applyRandomStyle()
		if (type === 1) {
			drawArcElement(x, y, w, int(random(4)));
		} else if (type === 2) {
			drawCircleElement(x, y, w);
		} else if (type === 3) {
			drawLineElement(x, y, w);
		}
	}
}

function drawArcElement(x, y, w, dir) {
	let d = w * 2;
	let a1 = 0;
	let a2 = PI / 2;
	let xx = x - (w / 2);
	let yy = y - (w / 2);

	if (dir === 1) {
		a1 = PI / 2; a2 = PI;
		xx = x + (w / 2);
	} else if (dir === 2) {
		a1 = PI; a2 = PI * 1.5;
		xx = x + (w / 2); yy = y + (w / 2);
	} else if (dir === 3) {
		a1 = PI * 1.5; a2 = TAU;
		yy = y + (w / 2);
	}
	arc(xx, yy, d, d, a1, a2);

	let n = int(random(3));
	let r = d / 2;
	for (let i = 0; i < n; i++) {
		let a = random(a1, a2);
		connectionNodes.push({ x: xx + r * cos(a), y: yy + r * sin(a), d: w });
	}
}

function drawCircleElement(x, y, w) {
	let d = w * random(0.1, 0.9);
	circle(x, y, d);

	let n = int(random(3));
	for (let i = 0; i < n; i++) {
		let a = random(TAU);
		let r = d / 2;
		let xx = x + r * cos(a);
		let yy = y + r * sin(a);
		connectionNodes.push({ x: xx, y: yy, d: w });
	}
}

function drawLineElement(x, y, w) {
	let xx = x + w * random(-1, 1) * 0.4;
	let yy = y + w * random(-1, 1) * 0.4;
	line(xx, y - (w / 2), xx, y + (w / 2));
	line(x - (w / 2), yy, x + (w / 2), yy);
	connectionNodes.push({ x: xx, y: yy, d: w });
}

function applyRandomStyle() {
	let thickness = width * random(0.001, 0.0003);
	let dashPattern = [0];
	let strokeColor = random(['#ffffff', '#119da4', '#d00000', '#ffba08']);

	if (random() < 0.5) {
		for (let i = 0; i < 5; i++) {
			dashPattern.push(width * random(0.002, 0.005));
		}
	}
	ctx.setLineDash(dashPattern);
	strokeWeight(thickness);
	stroke(strokeColor);
}

